/// What a label resolves to (WHATWG "get an encoding", before the departure noted
/// at `labels`). `unsupported` carries the WHATWG name of an encoding that is known
/// but not implemented.
pub const Target = union(enum) {
    page: Page,
    utf8,
    utf16le,
    utf16be,
    replacement,
    unsupported: []const u8,
};

pub const Label = struct { label: []const u8, target: Target };

