/// Look up an already trimmed, lowercased label.
pub fn lookupLabel(label: []const u8) ?Target {
    const Ctx = struct {
        fn order(key: []const u8, item: Label) std.math.Order {
            return std.mem.order(u8, key, item.label);
        }
    };
    const i = std.sort.binarySearch(Label, &labels, label, Ctx.order) orelse return null;
    return labels[i].target;
}
